struct V { float X, Y, Z; V() : X(0), Y(0), Z(0) {} V(float x, float y, float z) : X(x), Y(y), Z(z) {} };
static bool same(const V& a, const V& b) { return a.X == b.X && a.Y == b.Y && a.Z == b.Z; }
